import{_ as n,l as s,o as e,c as i,v as r,p as o,x as t,d,i as h,S as E}from"./chunks/framework.InCnrqk-.js";const b=JSON.parse('{"title":"嵌套循环与哈希连接","description":"","frontmatter":{"title":"嵌套循环与哈希连接","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/nlj-hash-join.md","filePath":"cs/nlj-hash-join.md","lastUpdated":1789023840000}'),p={name:"cs/nlj-hash-join.md"};function c(_,a,B,m,u,A){const l=s("Mermaid");return e(),i("div",null,[a[1]||(a[1]=r('<h1 id="嵌套循环与哈希连接" tabindex="-1">嵌套循环与哈希连接 <a class="header-anchor" href="#嵌套循环与哈希连接" aria-label="Permalink to &quot;嵌套循环与哈希连接&quot;">​</a></h1><div class="epigraph"><p>嵌套循环对每一外层元组探测内层；哈希连接把较小一侧建成桶，另一侧探测——代价形状完全不同。</p><footer>—— 据 Blasgen and Eswaran；Ramakrishnan and Gehrke 对 NLJ 与哈希连接的整理</footer></div><p><a href="/cs/join-algorithms">上一课</a>声明逻辑连接只有一种含义、物理有三种形状。本课不重写 ⋈ 的定义。缺口是前两种算子：块嵌套循环如何用缓冲池，哈希连接如何在内存不够时分区。排序归并下一课。NULL 不当成匹配键，<a href="/cs/sql-null">上一课三值</a> 已钉。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>连接算法总览留下名字。嵌套循环：简单，有索引时可变成「外层扫描 + 内层索引探测」。无索引则内层反复全表，I/O 灾难。哈希：等值连接上把 build 输入散到桶，probe 输入只扫一次；内存不够则 Grace 式分区再递归。缺口是<strong>何时选哪一种</strong>的机制，数字在代价课。</p><p><span class="marginnote">非等值连接（θ 不是等）哈希帮不上忙，循环或排序更合适。构建侧应是较小的那张（估计后）。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>块 NLJ：一次读外层 B 页，内层扫一遍，摊薄内层 I/O。索引 NLJ：内层条件是键，走 B+。哈希：选哈希函数，处理溢出桶；混合哈希把一部分常驻内存。本课不写具体 DBMS 的算子名。</p>',8)),(e(),o(E,null,{default:t(()=>[h(l,{id:"mermaid-22",class:"mermaid",graph:"flowchart%20TD%0A%20%20EQ%5B%22%E7%AD%89%E5%80%BC%E8%BF%9E%E6%8E%A5%22%5D%20--%3E%20NLJ%5B%22%E5%B5%8C%E5%A5%97%E5%BE%AA%E7%8E%AF%20%2F%20%E7%B4%A2%E5%BC%95%E6%8E%A2%E6%B5%8B%22%5D%0A%20%20EQ%20--%3E%20HJ%5B%22%E5%BB%BA%E5%93%88%E5%B8%8C%E8%A1%A8%E5%86%8D%E6%8E%A2%E6%B5%8B%22%5D%0A%20%20MEM%5B%22%E5%86%85%E5%AD%98%E4%B8%8D%E5%A4%9F%22%5D%20--%3E%20PART%5B%22%E5%88%86%E5%8C%BA%E5%90%8E%E5%86%8D%E5%93%88%E5%B8%8C%22%5D%0A"})]),fallback:t(()=>[...a[0]||(a[0]=[d(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=r('<h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>两种算子实现同一代数，但打破对称：哪一侧在外/build 改变页数。缓冲池偷页与脏页规则仍是 <a href="/cs/wal">WAL</a> 之前的那一套文件 I/O。选择率估错会选错 build 侧，后课直方图补统计。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不把并行 hash join 的全部网络 shuffle 写入主干。两边已按连接键有序时，归并可以一次扫描，下一课。</p><p>后课默认：等值连接常用循环或哈希。有序输入另有归并。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>NLJ 简单，索引时变成探测。</li><li>哈希适合等值且能放下或能分区。</li><li>排序归并下一课。</li><li>出处：Blasgen and Eswaran；Ramakrishnan and Gehrke。</li></ul>',7))])}const T=n(p,[["render",c]]);export{b as __pageData,T as default};
